"use strict";

// ============================================================
// 大正點陣機匯出
// 模板來源：使用者提供的 .numbers，已轉成 .xlsx 後嵌入。
// 版面 / 字型 / 儲存格位置請改 printer-config.js。
// ============================================================
const TAISHO_TEMPLATE_BASE64 = "";

function taishoRocDateParts(dateText) {
  const m = String(dateText || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return { year: "", month: "", day: "" };
  return {
    year: String(Number(m[1]) - 1911),
    month: m[2],
    day: m[3],
  };
}

function taishoDocumentText(type) {
  const t = String(type || "").trim();
  if (t.includes("進")) return "進";
  return "出";
}

function taishoSetRich(doc, address, value, fontCfg) {
  setOoxmlRichTextCell(doc, address, [{
    text: value ?? "",
    font: fontCfg.font,
    size: fontCfg.size,
  }]);
}

function taishoFormatKg(value) {
  return Number(value || 0).toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function taishoRemoveHeadersAndFooters(doc) {
  [...doc.getElementsByTagNameNS(OOXML_NS, "headerFooter")].forEach((n) => n.remove());
}

function fillTaishoSheetXml(templateXml, r) {
  const cfg = PRINTER_CONFIG.taisho;
  const c = cfg.cells;
  const f = cfg.fonts;
  const doc = parseXml(templateXml);
  const d = taishoRocDateParts(r.date);

  taishoRemoveHeadersAndFooters(doc);

  taishoSetRich(doc, c.rocYear, d.year, f.date);
  taishoSetRich(doc, c.month, d.month, f.date);
  taishoSetRich(doc, c.day, d.day, f.date);
  taishoSetRich(doc, c.documentType, taishoDocumentText(r.documentType), f.documentType);
  taishoSetRich(doc, c.deliveryNo, r.deliveryNo || "", f.deliveryNo);
  taishoSetRich(doc, c.tripNo, r.tripNo || "", f.tripNo);

  taishoSetRich(doc, c.customer, r.customer || "", f.customerLocation);
  taishoSetRich(doc, c.location, r.location || "", f.customerLocation);
  taishoSetRich(doc, c.driver, r.driver ? `(${r.driver})` : "", f.driver);
  taishoSetRich(doc, c.departureTime, r.departureTime || "", f.departureTime);

  // 注意：累計重量、調度員、車號、總重、空重、淨重是模板內的文字方塊，
  // 不能再寫進工作表儲存格，否則會和原文字方塊重疊。
  taishoSetRich(doc, c.oilLarge, r.oilLarge === "" ? "0" : (r.oilLarge || "0"), f.rightValues);
  taishoSetRich(doc, c.oilSmall, r.oilSmall === "" ? "0" : (r.oilSmall || "0"), f.rightValues);
  taishoSetRich(doc, c.product, r.productName || "", f.rightValues);

  const dimension = doc.getElementsByTagNameNS(OOXML_NS, "dimension")[0];
  if (dimension) dimension.setAttribute("ref", cfg.printArea);
  return serializeXml(doc);
}


function taishoSetDrawingShapeText(anchor, value) {
  const texts = [...anchor.getElementsByTagNameNS("http://schemas.openxmlformats.org/drawingml/2006/main", "t")];
  if (!texts.length) return;
  texts[0].textContent = value ?? "";
  // 同一文字方塊若有多個 run，清掉後續 run，避免舊文字殘留。
  for (let i = 1; i < texts.length; i++) texts[i].textContent = "";
}

function fillTaishoDrawingXml(templateXml, r) {
  const cfg = PRINTER_CONFIG.taisho;
  const doc = parseXml(templateXml);
  const root = doc.documentElement;
  const anchors = [...root.childNodes].filter((n) => n.nodeType === 1);
  const shape = cfg.drawingShapes;

  const setByIndex = (idx, value) => {
    const anchor = anchors[idx];
    if (anchor) taishoSetDrawingShapeText(anchor, value);
  };

  setByIndex(shape.tareWeight, taishoFormatKg(r.tareWeight));
  setByIndex(shape.grossWeight, taishoFormatKg(r.grossWeight));
  setByIndex(shape.netWeight, taishoFormatKg(r.netWeight));
  setByIndex(shape.cumulativeTons, ft(r.cumulativeTons));
  setByIndex(shape.vehicleNo, r.vehicleNo ? `${r.vehicleNo} /` : "");
  setByIndex(shape.dispatcher, r.dispatcher || "");

  return serializeXml(doc);
}

function taishoBuildSheetRelsXml(index) {
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="${PKG_REL_NS}"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing${index}.xml"/></Relationships>`;
}

function taishoRewriteWorkbookXml(templateXml, count) {
  const doc = parseXml(templateXml);
  const sheets = doc.getElementsByTagNameNS(OOXML_NS, "sheets")[0];
  while (sheets.firstChild) sheets.removeChild(sheets.firstChild);

  for (let i = 1; i <= count; i++) {
    const sheet = doc.createElementNS(OOXML_NS, "sheet");
    sheet.setAttribute("name", `車次${String(i).padStart(2, "0")}`);
    sheet.setAttribute("sheetId", String(i));
    sheet.setAttributeNS(REL_NS, "r:id", `rId${i + 2}`);
    sheets.appendChild(sheet);
  }

  let definedNames = doc.getElementsByTagNameNS(OOXML_NS, "definedNames")[0];
  if (!definedNames) {
    definedNames = doc.createElementNS(OOXML_NS, "definedNames");
    sheets.parentNode.insertBefore(definedNames, sheets.nextSibling);
  }
  while (definedNames.firstChild) definedNames.removeChild(definedNames.firstChild);
  for (let i = 0; i < count; i++) {
    const dn = doc.createElementNS(OOXML_NS, "definedName");
    dn.setAttribute("name", "_xlnm.Print_Area");
    dn.setAttribute("localSheetId", String(i));
    dn.textContent = `'車次${String(i + 1).padStart(2, "0")}'!$A$1:$AN$16`;
    definedNames.appendChild(dn);
  }
  return serializeXml(doc);
}

function taishoRewriteWorkbookRelsXml(templateXml, count) {
  const doc = parseXml(templateXml);
  const root = doc.documentElement;
  while (root.firstChild) root.removeChild(root.firstChild);

  const addRel = (id, type, target) => {
    const rel = doc.createElementNS(PKG_REL_NS, "Relationship");
    rel.setAttribute("Id", id);
    rel.setAttribute("Type", type);
    rel.setAttribute("Target", target);
    root.appendChild(rel);
  };

  addRel("rId1", "http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme", "theme/theme1.xml");
  addRel("rId2", "http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles", "styles.xml");
  for (let i = 1; i <= count; i++) {
    addRel(`rId${i + 2}`, "http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet", `worksheets/sheet${i}.xml`);
  }
  addRel(`rId${count + 3}`, "http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings", "sharedStrings.xml");
  return serializeXml(doc);
}

function taishoRewriteContentTypesXml(templateXml, count) {
  const doc = parseXml(templateXml);
  const root = doc.documentElement;
  [...root.getElementsByTagNameNS(CT_NS, "Override")].forEach((node) => {
    const part = node.getAttribute("PartName") || "";
    if (/^\/xl\/worksheets\/sheet\d+\.xml$/.test(part) ||
        /^\/xl\/drawings\/drawing\d+\.xml$/.test(part) ||
        part === "/xl/calcChain.xml") node.remove();
  });

  const addOverride = (part, type) => {
    const o = doc.createElementNS(CT_NS, "Override");
    o.setAttribute("PartName", part);
    o.setAttribute("ContentType", type);
    root.appendChild(o);
  };
  for (let i = 1; i <= count; i++) {
    addOverride(`/xl/worksheets/sheet${i}.xml`, "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml");
    addOverride(`/xl/drawings/drawing${i}.xml`, "application/vnd.openxmlformats-officedocument.drawing+xml");
  }
  return serializeXml(doc);
}

async function exportTaishoWorkbook() {
  if (!state.records.length) return alert("目前沒有生成資料，請先試算或匯入交貨表單。");
  if (typeof JSZip === "undefined") return alert("點陣機 Excel 模組未載入，請確認網路連線後重新整理。");

  const btn = el("taishoPrinterExportBtn");
  const oldText = btn.textContent;
  btn.disabled = true;
  btn.textContent = "產生【大正】檔案中…";

  try {
    const zip = await JSZip.loadAsync(TAISHO_TEMPLATE_BASE64, { base64: true });
    const templateSheetXml = await zip.file("xl/worksheets/sheet1.xml").async("string");
    const templateDrawingXml = await zip.file("xl/drawings/drawing1.xml").async("string");
    const workbookXml = await zip.file("xl/workbook.xml").async("string");
    const workbookRelsXml = await zip.file("xl/_rels/workbook.xml.rels").async("string");
    const contentTypesXml = await zip.file("[Content_Types].xml").async("string");

    Object.keys(zip.files).forEach((name) => {
      if (/^xl\/worksheets\/sheet\d+\.xml$/.test(name) ||
          /^xl\/worksheets\/_rels\/sheet\d+\.xml\.rels$/.test(name) ||
          /^xl\/drawings\/drawing\d+\.xml$/.test(name) ||
          name === "xl/calcChain.xml") {
        zip.remove(name);
      }
    });

    state.records.forEach((r, idx) => {
      const i = idx + 1;
      zip.file(`xl/worksheets/sheet${i}.xml`, fillTaishoSheetXml(templateSheetXml, r));
      zip.file(`xl/worksheets/_rels/sheet${i}.xml.rels`, taishoBuildSheetRelsXml(i));
      zip.file(`xl/drawings/drawing${i}.xml`, fillTaishoDrawingXml(templateDrawingXml, r));
    });

    zip.file("xl/workbook.xml", taishoRewriteWorkbookXml(workbookXml, state.records.length));
    zip.file("xl/_rels/workbook.xml.rels", taishoRewriteWorkbookRelsXml(workbookRelsXml, state.records.length));
    zip.file("[Content_Types].xml", taishoRewriteContentTypesXml(contentTypesXml, state.records.length));

    const blob = await zip.generateAsync({
      type: "blob",
      mimeType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      compression: "DEFLATE",
      compressionOptions: { level: 6 },
    });

    const batchDate = (state.records[0]?.date || el("date").value || today).replaceAll("-", "");
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `大正點陣機料單_${batchDate}.xlsx`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);

    toast(`已下載【大正】點陣機檔案，共 ${state.records.length} 車次`);
  } catch (err) {
    console.error(err);
    alert("【大正】點陣機檔案產生失敗。\n\n" + (err?.message || err));
  } finally {
    btn.disabled = false;
    btn.textContent = oldText;
  }
}
